cases = []
def case(level, category, refs, title, pre, steps, expected, criteria):
    cases.append(dict(id=f'T{len(cases)+1:03}', difficulty=level, functional_category=category,
        requirement_ids=refs.split(), task=title, preconditions=pre.split(' | '),
        test_data='Independent reset of F0 plus the named fixture; substitute TEST_ID and RUN_ID in all new labels. Credentials are injected privately at runtime, never stored in this suite.',
        expected_workflow=steps.split(' | '), expected_result=expected,
        pass_fail_criteria=criteria.split(' | '),
        independent_verification='Review the screenshots/action trace against EVERY criterion; inspect read-only persisted state or downloaded files where required. Agent self-report alone cannot establish PASS.'))

